import Foundation
import SwiftUI
#if canImport(AppKit)
import AppKit
#else
import UIKit
#endif

/// **The real logo of each AI provider**, on every Mac and on the iPhone, also where that provider's app is not
/// installed (the owner, 31 October 2026: "proper logos for chrome, claude, chatpgto and any other ai provider we
/// have", and his yes to the page that showed them). Each is the icon of the provider's own Mac app at 128 pixels. The
/// bytes stand here, so the apps still bundle no image file and read no network. The logos are their owners' marks:
/// Founderizer shows them only to name the provider.
public enum ProviderLogo {
    /// The logo of a runtime, nil for a provider that has none here.
    public static func image(_ runtime: String) -> Image? {
        switch runtime {
        case "claude": claude
        case "codex": chatGPT
        case "grok": grok
        default: nil
        }
    }

    private static let claude = decode(claudeBytes)
    private static let chatGPT = decode(chatGPTBytes)
    private static let grok = decode(grokBytes)

    private static func decode(_ bytes: String) -> Image? {
        guard let data = Data(base64Encoded: bytes) else { return nil }
        #if canImport(AppKit)
        return NSImage(data: data).map(Image.init(nsImage:))
        #else
        return UIImage(data: data).map(Image.init(uiImage:))
        #endif
    }

    // /Applications/Claude.app, electron.icns
    static let claudeBytes = ""
    // /Applications/ChatGPT.app, icon-chatgpt.icns
    static let chatGPTBytes = ""
    // /Applications/Grok Bot.app, icon.icns
    static let grokBytes = ""
}
